<?php require_once __DIR__.'/includes/functions.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$error='Enter a valid name/email and password with at least 8 characters.';else{try{$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$db->prepare("INSERT INTO users(name,email,password_hash,role,is_verified) VALUES(?,?,?,'user',0)");$s->bind_param('sss',$name,$email,$hash);$s->execute();$uid=$db->insert_id;$token=bin2hex(random_bytes(32));$th=hash('sha256',$token);$s=$db->prepare('INSERT INTO email_verifications(user_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 24 HOUR))');$s->bind_param('is',$uid,$th);$s->execute();$sent=send_verify_email($email,$name,$token);log_action('account_created','users',$uid,'Self-registration');$message=$sent?'Verification email sent. Check your inbox.':'Account created, but the local mail server did not send email. Configure PHP mail/SMTP and use Resend verification.';flash($message,$sent?'success':'warning');header('Location: '.url('login.php'));exit;}catch(mysqli_sql_exception $e){$error=$e->getCode()===1062?'That email is already registered.':'Unable to create account. Please try again.';}}}$title='Register';require 'includes/header.php';?>
<div class="panel" style="max-width:520px;margin:25px auto"><h1>Create user account</h1><p class="muted">New accounts are user/requester accounts and must verify their email.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Full name</label><input name="name" required maxlength="120"><label>Email</label><input type="email" name="email" required><label>Password (minimum 8 characters)</label><input type="password" name="password" minlength="8" required><button>Create account</button></form></div><?php require 'includes/footer.php';?>
